import{c as a,Q as s,j as n,m as t}from"./chunks/framework.DxgWTcNC.js";const m=JSON.parse('{"title":"Loading Binaries and Project Workflow","description":"","frontmatter":{},"headers":[],"relativePath":"part1/04-loading-binaries.md","filePath":"part1/04-loading-binaries.md","lastUpdated":null}'),i={name:"part1/04-loading-binaries.md"};function o(p,e,r,l,d,c){return s(),n("div",null,[...e[0]||(e[0]=[t(`<h1 id="loading-binaries-and-project-workflow" tabindex="-1">Loading Binaries and Project Workflow <a class="header-anchor" href="#loading-binaries-and-project-workflow" aria-label="Permalink to &quot;Loading Binaries and Project Workflow&quot;">​</a></h1><p>Half of embedded reverse engineering is loading the binary correctly. Once the architecture, base address, and section layout are right, the analysis commands you will learn in the rest of the book mostly Just Work. Get any one of those wrong and r2 will produce confident, plausible, completely wrong disassembly. This chapter covers how to load every file format you are likely to encounter in firmware work, and how to save your work in r2 projects so you do not redo it next session.</p><h2 id="elf-mach-o-pe-the-easy-case" tabindex="-1">ELF, Mach-O, PE: the easy case <a class="header-anchor" href="#elf-mach-o-pe-the-easy-case" aria-label="Permalink to &quot;ELF, Mach-O, PE: the easy case&quot;">​</a></h2><p>If your binary has a header r2 recognises, it Just Works:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>$ r2 firmware.elf</span></span>
<span class="line"><span>[0x08000ed8]&gt; i</span></span>
<span class="line"><span>file     firmware.elf</span></span>
<span class="line"><span>format   elf</span></span>
<span class="line"><span>arch     arm</span></span>
<span class="line"><span>bits     16              # Thumb</span></span>
<span class="line"><span>machine  ARM Cortex-M</span></span>
<span class="line"><span>class    ELF32</span></span>
<span class="line"><span>endian   little</span></span>
<span class="line"><span>...</span></span></code></pre></div><p><code>i</code> (info) shows what r2 figured out from the header. Confirm architecture, bits, and endian before you do anything else. For ELF firmware this is enough; r2 reads the program headers, maps the segments, and you can <code>aaa</code> and start reading.</p><p>If the file has debug info or symbols, r2 picks them up automatically. You can list them with <code>is</code> (symbols), <code>iI</code> (info), <code>ii</code> (imports), <code>iS</code> (sections), <code>iE</code> (exports).</p><h2 id="raw-flash-dumps" tabindex="-1">Raw flash dumps <a class="header-anchor" href="#raw-flash-dumps" aria-label="Permalink to &quot;Raw flash dumps&quot;">​</a></h2><p>The harder case: someone hands you a 16 MiB blob with no header. This is what comes out of an SPI flash reader, off a JTAG dump, or from <code>dd</code>-ing <code>/dev/mtdblockN</code> on a router. There is no metadata. You provide everything.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>$ r2 -a arm -b 16 -m 0x08000000 -e cfg.bigendian=false firmware.bin</span></span></code></pre></div><p>Flag by flag:</p><ul><li><code>-a arm</code> — architecture (<code>arm</code>, <code>mips</code>, <code>xtensa</code>, <code>riscv</code>, <code>8051</code>, <code>x86</code>, etc.)</li><li><code>-b 16</code> — bits (16 for Thumb, 32 for ARM/MIPS/RV32, 64 for AArch64)</li><li><code>-m 0x08000000</code> — map the file at this virtual address</li><li><code>-e cfg.bigendian=false</code> — endianness (true for big-endian MIPS)</li></ul><p>For some architectures you also need <code>-c</code> for the CPU variant:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>$ r2 -a arm -b 32 -c cortex -m 0x08000000 firmware.bin</span></span>
<span class="line"><span>$ r2 -a xtensa -c esp32 -m 0x40080000 firmware.bin</span></span>
<span class="line"><span>$ r2 -a riscv -b 32 -c rv32imac -m 0x42000000 firmware.bin</span></span></code></pre></div><p>The CPU subtype matters: Cortex-A and Cortex-M share the ARMv7 encoding but have different system registers; the M-profile MSR instructions decode incorrectly with the wrong <code>-c</code>.</p><div class="warning custom-block"><p class="custom-block-title">Warning</p><p>If you do not provide <code>-m</code>, the file is mapped at <code>0x0</code> by default. For Cortex-M firmware this means every absolute address in the binary (vector table entries, literal pools) is offset by the actual flash base (<code>0x08000000</code> for STM32, <code>0x00020000</code> for nRF52 application image, etc.). The disassembly looks fine until you try to follow a reference and land in nothing.</p></div><h3 id="discovering-the-architecture" tabindex="-1">Discovering the architecture <a class="header-anchor" href="#discovering-the-architecture" aria-label="Permalink to &quot;Discovering the architecture&quot;">​</a></h3><p>If you do not know the architecture, the strings command is your first move:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>$ strings firmware.bin | grep -iE &#39;arm|cortex|gcc|clang|esp|stm32|nrf&#39;</span></span></code></pre></div><p><code>gcc</code> and <code>clang</code> build IDs leak the target. Vendor strings (<code>STM32CubeIDE</code>, <code>nRF Connect SDK</code>, <code>Espressif IoT Development Framework</code>) tell you the SoC family.</p><p>Strings rarely tell you the <em>bits</em>. For that, look at byte distribution:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>$ python3 -c &#39;</span></span>
<span class="line"><span>import sys, collections</span></span>
<span class="line"><span>d = open(sys.argv[1],&quot;rb&quot;).read()</span></span>
<span class="line"><span>c = collections.Counter(d)</span></span>
<span class="line"><span>print(&quot;most common:&quot;, c.most_common(8))</span></span>
<span class="line"><span>&#39; firmware.bin</span></span></code></pre></div><p>ARM 32-bit code has a high frequency of <code>0xe5</code> (LDR/STR with register). Thumb code is denser and shows <code>0x46</code> (MOV register) and <code>0x47</code> (BX). MIPS code is full of <code>0x00</code> from the upper bytes of zeros and the delay slot NOP. RISC-V is variable-width and looks more uniform. Xtensa LX has 24-bit instructions and is lumpy.</p><p>A better tool is <strong>binwalk</strong>:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>$ binwalk -A firmware.bin   # opcode-pattern detection across the file</span></span></code></pre></div><p><code>binwalk -A</code> runs Capstone disassembly heuristics across multiple architectures and tells you which fits best. It is wrong sometimes; treat it as a strong hint, not gospel.</p><p>A better-still tool is <strong>ISA detection scripts</strong> like <code>cpu_rec.py</code> (Airbus CERT) which use byte n-gram statistics. These classify Xtensa, AVR, 8051, V850, and other oddballs reliably.</p><h3 id="discovering-the-load-address" tabindex="-1">Discovering the load address <a class="header-anchor" href="#discovering-the-load-address" aria-label="Permalink to &quot;Discovering the load address&quot;">​</a></h3><p>The vector table is your friend. On Cortex-M the first word is the initial stack pointer; the second word is the reset vector. Both must be within RAM and FLASH respectively:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>$ xxd firmware.bin | head -2</span></span>
<span class="line"><span>00000000: 00f0 0220 d113 0008 1d14 0008 1f14 0008</span></span>
<span class="line"><span>00000010: 2114 0008 2314 0008 0000 0000 0000 0000</span></span></code></pre></div><ul><li>SP = <code>0x2002f000</code> — clearly RAM (RAM bases at <code>0x20000000</code> on STM32)</li><li>Reset = <code>0x080013d1</code> — flash code (flash bases at <code>0x08000000</code>); the <code>1</code> low bit means Thumb mode</li><li>The next handlers (<code>0x0800141d</code>, etc.) all live in the same flash window</li></ul><p>So the image is mapped at <code>0x08000000</code>. Build the command:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>$ r2 -a arm -b 16 -m 0x08000000 firmware.bin</span></span></code></pre></div><p>For other architectures, the equivalent reasoning applies — see Part III&#39;s per-architecture chapters for what the first few words usually look like.</p><h2 id="format-specific-loaders" tabindex="-1">Format-specific loaders <a class="header-anchor" href="#format-specific-loaders" aria-label="Permalink to &quot;Format-specific loaders&quot;">​</a></h2><h3 id="intel-hex-s-record" tabindex="-1">Intel HEX, S-Record <a class="header-anchor" href="#intel-hex-s-record" aria-label="Permalink to &quot;Intel HEX, S-Record&quot;">​</a></h3><p><code>.hex</code> (Intel HEX) and <code>.s19</code>/<code>.srec</code> files are ASCII representations of binary with embedded address records. R2 reads them natively:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>$ r2 firmware.hex</span></span></code></pre></div><p>R2 figures out the load addresses from the records. You still set <code>-a</code> and <code>-b</code> because the format does not encode architecture.</p><p>You can also convert ahead of time with <code>objcopy</code>:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>$ arm-none-eabi-objcopy -I ihex -O binary firmware.hex firmware.bin</span></span></code></pre></div><h3 id="uf2" tabindex="-1">UF2 <a class="header-anchor" href="#uf2" aria-label="Permalink to &quot;UF2&quot;">​</a></h3><p>UF2 (USB Flashing Format, used by Microsoft, Adafruit, RP2040 boards) is a 512-byte-block format with embedded target addresses and family IDs. R2 has a UF2 plugin in recent versions; otherwise convert:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>$ uf2conv -c -o firmware.bin firmware.uf2</span></span></code></pre></div><p>Or use the Python package <code>uf2utils</code>. The result is a flat binary you load with <code>-m</code>.</p><h3 id="esp-image-format" tabindex="-1">ESP image format <a class="header-anchor" href="#esp-image-format" aria-label="Permalink to &quot;ESP image format&quot;">​</a></h3><p>ESP32 firmware uses Espressif&#39;s own image container. Each <code>.bin</code> has an 8-byte header followed by segments, each with its own load address. Use <strong>esptool.py</strong> to extract:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>$ esptool.py --chip esp32 image_info firmware.bin</span></span>
<span class="line"><span>File size: 1048576 (bytes)</span></span>
<span class="line"><span>Image version: 1</span></span>
<span class="line"><span>Entry point: 40080d20</span></span>
<span class="line"><span>2 segments</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Segment 1: len 0x07b48 load 0x40080000 file_offs 0x00000018</span></span>
<span class="line"><span>Segment 2: len 0x0d2a4 load 0x3ffb0000 file_offs 0x00007b68</span></span>
<span class="line"><span>...</span></span></code></pre></div><p>Then either dump each segment to its own file and load them as separate mappings, or use the r2 ESP image loader (<code>r2pm -ci esp_image_loader</code> in some forks). Chapter 14 covers the ESP-specific workflow.</p><h3 id="bootloader-stripped-images" tabindex="-1">Bootloader-stripped images <a class="header-anchor" href="#bootloader-stripped-images" aria-label="Permalink to &quot;Bootloader-stripped images&quot;">​</a></h3><p>Some images have a small header you need to skip — Realtek WiFi modules, TI CC chips, Allwinner SoCs. <code>binwalk firmware.bin</code> typically identifies the boundary:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>$ binwalk firmware.bin</span></span>
<span class="line"><span>DECIMAL    HEXADECIMAL  DESCRIPTION</span></span>
<span class="line"><span>0          0x0          Realtek firmware header, ...</span></span>
<span class="line"><span>512        0x200        ARM executable code (Thumb)</span></span></code></pre></div><p>Then strip with <code>dd</code>:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>$ dd if=firmware.bin of=stripped.bin bs=1 skip=512</span></span></code></pre></div><p>Or load directly with an offset:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>$ r2 -a arm -b 16 -m 0x08000000 -B 512 firmware.bin</span></span></code></pre></div><p><code>-B</code> is the in-file offset to start from. R2 maps from there, treating the rest of the file as the loadable image.</p><h2 id="multiple-files-multiple-mappings" tabindex="-1">Multiple files / multiple mappings <a class="header-anchor" href="#multiple-files-multiple-mappings" aria-label="Permalink to &quot;Multiple files / multiple mappings&quot;">​</a></h2><p>For firmware where code lives at one address and data at another (which is most embedded), open multiple files into the same r2 session:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>$ r2 -a arm -b 16 -m 0x08000000 code.bin</span></span>
<span class="line"><span>[0x08000000]&gt; o data.bin 0x20000000   # map data.bin at 0x20000000</span></span>
<span class="line"><span>[0x08000000]&gt; o                       # list mappings</span></span>
<span class="line"><span> 1 -- /path/code.bin @ 0x08000000 ...</span></span>
<span class="line"><span> 2 -- /path/data.bin @ 0x20000000 ...</span></span></code></pre></div><p>This is how you reconstruct the runtime memory map when the linker script puts code in flash and initial RAM contents in a separate region of flash.</p><p>You can also do this from the command line:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>$ r2 -a arm -b 16 -m 0x08000000 -i load.r2 code.bin</span></span></code></pre></div><p>Where <code>load.r2</code> is a script of <code>o</code> commands and other r2 commands run on startup. Save your loading recipe — you will reload the same firmware many times.</p><h2 id="projects" tabindex="-1">Projects <a class="header-anchor" href="#projects" aria-label="Permalink to &quot;Projects&quot;">​</a></h2><p>A radare2 project saves your analysis state — function names, comments, types, flags, configuration — to disk so you can resume later.</p><p>Save the current session:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>[0x08000000]&gt; Ps router-fw-2024-05      # save project</span></span></code></pre></div><p>Open later:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>$ r2 -p router-fw-2024-05</span></span></code></pre></div><p>Projects are stored under <code>~/.config/radare2/projects/&lt;name&gt;/</code>. Each is a directory with the binary&#39;s metadata and your annotations. Commit them to git if you are working on a long reverse-engineering effort with others — projects are largely text and diff well.</p><div class="tip custom-block"><p class="custom-block-title">Tip</p><p>Make a project save part of your routine. After every meaningful session — every time you would close a tab in IDA — <code>Ps</code>. There is no auto-save; an r2 crash mid-session loses unsaved work.</p></div><div class="warning custom-block"><p class="custom-block-title">Warning</p><p>Project saves do not save the binary itself, only the analysis state plus a path back to the original file. If you move or rename the binary, the project will not find it. Either keep paths stable or save the binary inside the project directory and edit the project file&#39;s path.</p></div><h2 id="a-reproducible-loading-script" tabindex="-1">A reproducible loading script <a class="header-anchor" href="#a-reproducible-loading-script" aria-label="Permalink to &quot;A reproducible loading script&quot;">​</a></h2><p>For any binary you will work on for more than 20 minutes, write a loading script. Example for an STM32F4 firmware:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span># load.r2</span></span>
<span class="line"><span>e asm.arch=arm</span></span>
<span class="line"><span>e asm.bits=16</span></span>
<span class="line"><span>e asm.cpu=cortex</span></span>
<span class="line"><span>e cfg.bigendian=false</span></span>
<span class="line"><span></span></span>
<span class="line"><span># memory map</span></span>
<span class="line"><span>o stm32f4-firmware.bin 0x08000000</span></span>
<span class="line"><span></span></span>
<span class="line"><span># label common peripheral bases</span></span>
<span class="line"><span>f rcc.base = 0x40023800</span></span>
<span class="line"><span>f gpioa.base = 0x40020000</span></span>
<span class="line"><span>f gpiob.base = 0x40020400</span></span>
<span class="line"><span>f usart1.base = 0x40011000</span></span>
<span class="line"><span>f usart2.base = 0x40004400</span></span>
<span class="line"><span></span></span>
<span class="line"><span># vector table</span></span>
<span class="line"><span>af reset_handler @ 0x080001cd</span></span>
<span class="line"><span>afn reset_handler 0x080001cd</span></span>
<span class="line"><span></span></span>
<span class="line"><span># project</span></span>
<span class="line"><span>P+ stm32f4-fw</span></span></code></pre></div><p>Run it:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>$ r2 -i load.r2 -</span></span></code></pre></div><p>Or include it in <code>Ps</code> and you can reproduce the same starting state every time. The next chapter takes a loaded binary and walks through r2&#39;s analysis pipeline.</p>`,79)])])}const u=a(i,[["render",o]]);export{m as __pageData,u as default};
